        end
        for (i = 0; i < 8; i = i + 1) begin : g_se
            ot_psf_mx1 u_mx7 (.s(r4_sub[((27 + i) * SC) / 35]), .a(exp_sub[i]), .b(r4_eadd[i]), .y(s2_exp[i]));
        end
    endgenerate
    wire inc = s2_val[2] && ((|s2_val[1:0]) || s2_val[3]);
    wire [23:0] rnd_w; wire rnd_cw;
    ot_psf_inc #(.W(24)) u_rnd (.a(s2_val[26:3]), .inc(inc), .y(rnd_w), .co(rnd_cw));
    (* keep *) reg r5_v; (* keep *) reg r5_sign, r5_zero; (* keep *) reg [1:0] r5_err; (* keep *) reg [31:0] r5_code; (* keep *) reg [7:0] r5_exp; (* keep *) reg [23:0] r5_rnd;
    (* keep *) reg r5_ov0, r5_ov1;
    (* keep *) reg [RC-1:0] r5_rc;
    (* keep *) reg [BC-1:0] r5_byp;
    (* keep *) reg [1:0] r5_k0, r5_k1;                               // zero | over (round carry 0 / 1), per half
    always @(posedge clk or negedge rst_n) if (!rst_n) r5_v <= 1'b0; else r5_v <= r4_v;
    always @(posedge clk) begin
        r5_sign <= r4_sign; r5_zero <= r4_zero; r5_err <= r4_err; r5_code <= r4_code; r5_exp <= s2_exp;
        r5_rnd <= rnd_w; r5_rc <= {RC{rnd_cw}}; r5_byp <= {BC{r4_byp}};
        r5_ov0 <= (s2_exp == 8'hff); r5_ov1 <= (s2_exp >= 8'hfe);
        r5_k0 <= {2{r4_zero || (s2_exp == 8'hff)}}; r5_k1 <= {2{r4_zero || (s2_exp >= 8'hfe)}};
    end
    // ------------------------------------------------------------ Y
    (* keep *) wire [23:0] man;
    generate for (i = 0; i < 24; i = i + 1) begin : g_man
        wire c = r5_rc[(i * RC) / 25];
        if (i == 23) begin : g_t
            ot_psf_mx1 u_mxm (.s(c), .a(1'b1), .b(r5_rnd[23]), .y(man[23]));
        end else begin : g_n
            ot_psf_mx1 u_mxm (.s(c), .a(r5_rnd[i + 1]), .b(r5_rnd[i]), .y(man[i]));
        end
    end endgenerate
    wire [7:0] e8; wire e_c;
    ot_psf_inc #(.W(8)) u_e (.a(r5_exp), .inc(r5_rc[RC-1]), .y(e8), .co(e_c));
    wire subn = (e8 == 8'd1) && !e_c && !man[23];
    wire [30:0] code = {subn ? 8'd0 : e8, man[22:0]};
    wire kl0 = r5_rc[0] ? r5_k1[0] : r5_k0[0];
    wire kl1 = r5_rc[RC-1] ? r5_k1[1] : r5_k0[1];
    wire over = r5_rc[RC-1] ? r5_ov1 : r5_ov0;
    wire [31:0] yn;
    generate for (i = 0; i < 31; i = i + 1) begin : g_y
        ot_psf_mx1 u_mx8 (.s(r5_byp[(i * BC) / 32]), .a(r5_code[i]), .b((!((i < 16) ? kl0 : kl1) && code[i])), .y(yn[i]));
    end endgenerate
    ot_psf_mx1 u_mx9 (.s(r5_byp[BC-1]), .a(r5_code[31]), .b((!kl1 && (code != 31'd0) && r5_sign)), .y(yn[31]));
    always @(posedge clk or negedge rst_n) if (!rst_n) valid_out <= 1'b0; else valid_out <= r5_v;
    always @(posedge clk) begin
        y <= yn;
        err <= r5_byp[BC-1] ? r5_err : (r5_zero ? 2'd0 : (over ? 2'd2 : 2'd0));
    end
endmodule

// =====================================================================================================================
// binary32 multiply, bit for bit ot_hdc_fp32_mul_f12 (= ot_hdc_fp32_mul_lat).  LAT 7:
//   A in -> R1  decode, fraction LZC, one-hot normalise shift, powers
//   B R1 -> R2  one-hot normalise, power sum
//   C R2 -> R3  AND rows, five carry-save levels (24 -> 4)
//   D R3 -> R4  two carry-save levels (4 -> 2), floors, encode fields, one-hot subnormal shift
//   E R4 -> R5  48-bit prefix add; top / sub copies
//   F R5 -> R6  select (top copies), one-hot subnormal shift, round / sticky, is_sub copies, round-carry copies
//   Y R6 -> y   round increment, encode (carry / sub / overflow copies)
// =====================================================================================================================
module ot_psf_mul (
    input  wire clk, input wire rst_n, input wire valid_in, input wire [31:0] a, input wire [31:0] b,
    (* keep *) output reg [31:0] y, (* keep *) output reg [1:0] err, (* keep *) output reg valid_out
);
    localparam integer TC = 6 * `PSF_X, IC = 4 * `PSF_X, RC = 4 * `PSF_X, OC = 4 * `PSF_X, BC = 2 * `PSF_X;
    function automatic [95:0] csa(input [47:0] r0, input [47:0] r1, input [47:0] r2);
        begin csa[47:0] = r0 ^ r1 ^ r2; csa[95:48] = ((r0 & r1) | (r0 & r2) | (r1 & r2)) << 1; end
    endfunction
    genvar i, d;
    // ------------------------------------------------------------ A
    wire [7:0] af = a[30:23], bf = b[30:23];
    wire nf = (af == 8'hff) || (bf == 8'hff);
    wire zero = (a[30:0] == 31'd0) || (b[30:0] == 31'd0);
    wire [5:0] a_cz, b_cz;
    ot_psf_lzc32 u_la (.x({a[22:0], 9'h1ff}), .n(a_cz));
    ot_psf_lzc32 u_lb (.x({b[22:0], 9'h1ff}), .n(b_cz));
    wire a_s = (af == 8'd0), b_s = (bf == 8'd0);
    wire [4:0] am = a_cz[4:0] & {5{a_s}}, bm = b_cz[4:0] & {5{b_s}};
    wire [4:0] ash = am + {4'd0, a_s}, bsh = bm + {4'd0, b_s};       // subnormal: clz23 + 1, normal: 0
    (* keep *) reg r1_v; (* keep *) reg r1_byp, r1_sign; (* keep *) reg [1:0] r1_err;
    (* keep *) reg [23:0] r1_av, r1_bv; (* keep *) reg [24:0] r1_ao, r1_bo; (* keep *) reg [11:0] r1_ap, r1_bp;
    always @(posedge clk or negedge rst_n) if (!rst_n) r1_v <= 1'b0; else r1_v <= valid_in;
    always @(posedge clk) begin
        r1_byp <= nf || zero; r1_err <= nf ? 2'd1 : 2'd0; r1_sign <= a[31] ^ b[31];
        r1_av <= {!a_s, a[22:0]}; r1_bv <= {!b_s, b[22:0]};
        r1_ap <= {4'd0, af} - 12'd150 - {7'd0, am}; r1_bp <= {4'd0, bf} - 12'd150 - {7'd0, bm};
    end
    wire [24:0] ao_w, bo_w;
    ot_psf_oh5 #(.N(25)) u_ao (.en(1'b1), .x(ash), .oh(ao_w));
    ot_psf_oh5 #(.N(25)) u_bo (.en(1'b1), .x(bsh), .oh(bo_w));
    always @(posedge clk) begin r1_ao <= ao_w; r1_bo <= bo_w; end
    // ------------------------------------------------------------ B
    wire [23:0] a_n, b_n;
    generate for (i = 0; i < 24; i = i + 1) begin : g_n
        wire [23:0] ta, tb;
        for (d = 0; d < 24; d = d + 1) begin : g_t
            if (d <= i) begin : g_in
                assign ta[d] = r1_ao[d] & r1_av[i - d];
                assign tb[d] = r1_bo[d] & r1_bv[i - d];
            end else begin : g_out
                assign ta[d] = 1'b0; assign tb[d] = 1'b0;
            end
        end
        assign a_n[i] = |ta; assign b_n[i] = |tb;
    end endgenerate
    wire [11:0] pw; wire pw_c;
    ot_psf_ks #(.W(12)) u_pw (.a(r1_ap), .b(r1_bp), .cin(1'b0), .s(pw), .cout(pw_c));
    (* keep *) reg r2_v; (* keep *) reg r2_byp, r2_sign; (* keep *) reg [1:0] r2_err; (* keep *) reg [23:0] r2_a, r2_b; (* keep *) reg [11:0] r2_pw;
    always @(posedge clk or negedge rst_n) if (!rst_n) r2_v <= 1'b0; else r2_v <= r1_v;
    always @(posedge clk) begin
        r2_byp <= r1_byp; r2_err <= r1_err; r2_sign <= r1_sign; r2_a <= a_n; r2_b <= b_n; r2_pw <= pw;
    end
    // ------------------------------------------------------------ C
    wire [48*8-1:0] rows;
    ot_psf_rows u_rows (.a(r2_a), .b(r2_b), .rows(rows));
    wire [48*6-1:0] l4;
    wire [48*4-1:0] l5;
    generate
        for (i = 0; i < 2; i = i + 1) begin : g_l4
            assign l4[96*i +: 96] = csa(rows[144*i +: 48], rows[144*i + 48 +: 48], rows[144*i + 96 +: 48]);
        end
        assign l4[192 +: 96] = rows[288 +: 96];
        for (i = 0; i < 2; i = i + 1) begin : g_l5
            assign l5[96*i +: 96] = csa(l4[144*i +: 48], l4[144*i + 48 +: 48], l4[144*i + 96 +: 48]);
        end
    endgenerate
    (* keep *) reg r3_v; (* keep *) reg r3_byp, r3_sign; (* keep *) reg [1:0] r3_err; (* keep *) reg [48*4-1:0] r3_l5;
    (* keep *) reg [11:0] r3_pw, r3_pwb, r3_pwc;                     // power copies: 47 path | 46 path | subnormal shift
    always @(posedge clk or negedge rst_n) if (!rst_n) r3_v <= 1'b0; else r3_v <= r2_v;
    always @(posedge clk) begin
        r3_byp <= r2_byp; r3_err <= r2_err; r3_sign <= r2_sign; r3_l5 <= l5;
        r3_pw <= r2_pw; r3_pwb <= r2_pw; r3_pwc <= r2_pw;
    end
    // ------------------------------------------------------------ D
    wire [48*3-1:0] l6;
    wire [48*2-1:0] l7;
    assign l6[0 +: 96] = csa(r3_l5[0 +: 48], r3_l5[48 +: 48], r3_l5[96 +: 48]);
    assign l6[96 +: 48] = r3_l5[144 +: 48];
    assign l7 = csa(l6[0 +: 48], l6[48 +: 48], l6[96 +: 48]);
    wire signed [11:0] power = r3_pw, powb = r3_pwb, powc = r3_pwc;
    wire signed [11:0] fl47 = power + 12'sd47, fl46 = powb + 12'sd46;
    wire signed [11:0] f47p1 = power + 12'sd48, f46p1 = powb + 12'sd47;
    wire signed [11:0] sh_sub = -(powc + 12'sd149);
    // one-hot subnormal shift: index d - 24 for sh_sub = d in [24, 48], index 25 for sh_sub >= 49 (only sh_sub >= 24
    // can be a subnormal result: fl46 < -126 <=> power <= -173 <=> sh_sub >= 24)
    wire [2:0] shh = sh_sub[5:3], shl = sh_sub[2:0];
    wire sh_lo = (sh_sub[11:6] == 6'd0);
    (* keep *) wire [7:0] ph, pl;
    generate for (i = 0; i < 8; i = i + 1) begin : g_pd
        assign ph[i] = sh_lo && (shh == i);
        assign pl[i] = (shl == i);
    end endgenerate
    wire sh_ge49 = !sh_sub[11] && (!sh_lo || (sh_sub[5:0] >= 6'd49));
    wire [25:0] soh;
    generate for (d = 24; d <= 48; d = d + 1) begin : g_soh
        assign soh[d - 24] = ph[d / 8] & pl[d % 8];
    end endgenerate
    assign soh[25] = sh_ge49;
    (* keep *) reg r4_v; (* keep *) reg r4_byp, r4_sign; (* keep *) reg [1:0] r4_err; (* keep *) reg [95:0] r4_l7; (* keep *) reg r4_s47, r4_s46;
    (* keep *) reg [7:0] r4_fa47, r4_fb47, r4_fa46, r4_fb46; (* keep *) reg r4_oa47, r4_ob47, r4_oa46, r4_ob46; (* keep *) reg [25:0] r4_soh;
    always @(posedge clk or negedge rst_n) if (!rst_n) r4_v <= 1'b0; else r4_v <= r3_v;
    always @(posedge clk) begin
        r4_byp <= r3_byp; r4_err <= r3_err; r4_sign <= r3_sign; r4_l7 <= l7;
        r4_s47 <= (fl47 < -12'sd126); r4_s46 <= (fl46 < -12'sd126);
        r4_fa47 <= fl47[7:0] + 8'd127; r4_fb47 <= f47p1[7:0] + 8'd127;
        r4_fa46 <= fl46[7:0] + 8'd127; r4_fb46 <= f46p1[7:0] + 8'd127;
        r4_oa47 <= (fl47 > 12'sd127); r4_ob47 <= (f47p1 > 12'sd127);
        r4_oa46 <= (fl46 > 12'sd127); r4_ob46 <= (f46p1 > 12'sd127);
        r4_soh <= soh;
    end
    // ------------------------------------------------------------ E
    wire [47:0] prod; wire prod_c;
    ot_psf_ks #(.W(48)) u_cpa (.a(r4_l7[47:0]), .b(r4_l7[95:48]), .cin(1'b0), .s(prod), .cout(prod_c));
    (* keep *) reg r5_v; (* keep *) reg r5_byp, r5_sign; (* keep *) reg [1:0] r5_err;
    (* keep *) reg [47:0] r5_p;                                      // kept: p[47] must not fold into a top copy
    (* keep *) reg [7:0] r5_fa47, r5_fb47, r5_fa46, r5_fb46; (* keep *) reg r5_oa47, r5_ob47, r5_oa46, r5_ob46; (* keep *) reg [25:0] r5_soh;
    (* keep *) reg [TC-1:0] r5_top;
    (* keep *) reg [IC-1:0] r5_s47, r5_s46;
    always @(posedge clk or negedge rst_n) if (!rst_n) r5_v <= 1'b0; else r5_v <= r4_v;
    always @(posedge clk) begin
        r5_byp <= r4_byp; r5_err <= r4_err; r5_sign <= r4_sign; r5_p <= prod; r5_top <= {TC{prod[47]}};
        r5_s47 <= {IC{r4_s47}}; r5_s46 <= {IC{r4_s46}};
        r5_fa47 <= r4_fa47; r5_fb47 <= r4_fb47; r5_fa46 <= r4_fa46; r5_fb46 <= r4_fb46;
        r5_oa47 <= r4_oa47; r5_ob47 <= r4_ob47; r5_oa46 <= r4_oa46; r5_ob46 <= r4_ob46; r5_soh <= r4_soh;
    end
    // ------------------------------------------------------------ F
    // top-selected fields on top copies: n_main 24 | fa 8 | fb 8 | oa | ob | n_rb | n_st | is_sub (IC) = 44 + IC
    localparam integer NT = 44 + IC;
    (* keep *) wire [23:0] n_main; (* keep *) wire [7:0] fa, fb; (* keep *) wire oa, ob, n_rb, n_st;
    (* keep *) wire [IC-1:0] isub;
    generate
        for (i = 0; i < 24; i = i + 1) begin : g_nm
            ot_psf_mx1 u_mx10 (.s(r5_top[(i * TC) / NT]), .a(r5_p[24 + i]), .b(r5_p[23 + i]), .y(n_main[i]));
        end
        for (i = 0; i < 8; i = i + 1) begin : g_f
            ot_psf_mx1 u_mx11 (.s(r5_top[((24 + i) * TC) / NT]), .a(r5_fa47[i]), .b(r5_fa46[i]), .y(fa[i]));
            ot_psf_mx1 u_mx12 (.s(r5_top[((32 + i) * TC) / NT]), .a(r5_fb47[i]), .b(r5_fb46[i]), .y(fb[i]));
        end
        for (i = 0; i < IC; i = i + 1) begin : g_is
            ot_psf_mx1 u_mx13 (.s(r5_top[((44 + i) * TC) / NT]), .a(r5_s47[i]), .b(r5_s46[i]), .y(isub[i]));
        end
    endgenerate
    ot_psf_mx1 u_mx14 (.s(r5_top[(40 * TC) / NT]), .a(r5_oa47), .b(r5_oa46), .y(oa));
    ot_psf_mx1 u_mx15 (.s(r5_top[(41 * TC) / NT]), .a(r5_ob47), .b(r5_ob46), .y(ob));
    ot_psf_mx1 u_mx16 (.s(r5_top[(42 * TC) / NT]), .a(r5_p[23]), .b(r5_p[22]), .y(n_rb));
    assign n_st = (|r5_p[21:0]) || (r5_top[(43 * TC) / NT] && r5_p[22]);
    wire [47:0] ppre;                                                // ppre[k] = |p[k:0]
    assign ppre[0] = r5_p[0];
    generate for (i = 1; i < 48; i = i + 1) begin : g_pp
        assign ppre[i] = ppre[i-1] | r5_p[i];
    end endgenerate
    wire [23:0] s_main;
    generate for (i = 0; i < 24; i = i + 1) begin : g_sm
        wire [23:0] t;
        for (d = 24; d < 48; d = d + 1) begin : g_t
            if (i + d < 48) begin : g_in
                assign t[d - 24] = r5_soh[d - 24] & r5_p[i + d];
            end else begin : g_out
                assign t[d - 24] = 1'b0;
            end
        end
        assign s_main[i] = |t;
    end endgenerate
    wire [24:0] trb, tst;
    generate for (d = 24; d <= 48; d = d + 1) begin : g_rs
        assign trb[d - 24] = r5_soh[d - 24] & r5_p[d - 1];
        assign tst[d - 24] = r5_soh[d - 24] & ppre[d - 2];
    end endgenerate
    wire s_rb = |trb;
    wire s_st = (|tst) || (r5_soh[25] && ppre[47]);
    // is_sub selects: main 24 | rb | st = 26 bits over IC copies
    (* keep *) wire [23:0] main; (* keep *) wire rb, st;
    generate for (i = 0; i < 24; i = i + 1) begin : g_mn
        ot_psf_mx1 u_mx17 (.s(isub[(i * IC) / 26]), .a(s_main[i]), .b(n_main[i]), .y(main[i]));
    end endgenerate
    ot_psf_mx1 u_mx18 (.s(isub[(24 * IC) / 26]), .a(s_rb), .b(n_rb), .y(rb));
    ot_psf_mx1 u_mx19 (.s(isub[(25 * IC) / 26]), .a(s_st), .b(n_st), .y(st));
    wire inc = rb && (st || main[0]);
    wire rcy = inc && (&main);
    (* keep *) reg r6_v; (* keep *) reg r6_sign; (* keep *) reg [1:0] r6_err; (* keep *) reg [23:0] r6_main; (* keep *) reg r6_inc; (* keep *) reg [7:0] r6_fa, r6_fb;
    (* keep *) reg [BC-1:0] r6_byp;
    (* keep *) reg [OC-1:0] r6_sub;
    (* keep *) reg [RC-1:0] r6_rc;
    (* keep *) reg [1:0] r6_oa, r6_ob;
    always @(posedge clk or negedge rst_n) if (!rst_n) r6_v <= 1'b0; else r6_v <= r5_v;
    always @(posedge clk) begin
        r6_sign <= r5_sign; r6_err <= r5_err; r6_byp <= {BC{r5_byp}}; r6_main <= main; r6_inc <= inc;
        r6_fa <= fa; r6_fb <= fb; r6_oa <= {2{oa}}; r6_ob <= {2{ob}}; r6_rc <= {RC{rcy}};
    end
    generate for (i = 0; i < OC; i = i + 1) begin : g_sc
        always @(posedge clk) r6_sub[i] <= isub[i];
    end endgenerate
    // ------------------------------------------------------------ Y
    wire [23:0] rnd; wire rnd_co;
    ot_psf_inc #(.W(24)) u_rnd (.a(r6_main), .inc(r6_inc), .y(rnd), .co(rnd_co));
    // carry = !sub && round carry; man 23 | field 8 on the RC copies
    wire [RC-1:0] cy;
    generate for (i = 0; i < RC; i = i + 1) begin : g_cy
        assign cy[i] = !r6_sub[(i * OC) / RC] && r6_rc[i];
    end endgenerate
    (* keep *) wire [22:0] man; (* keep *) wire [7:0] field;
    generate
        for (i = 0; i < 23; i = i + 1) begin : g_m
            ot_psf_mx1 u_mx20 (.s(cy[(i * RC) / 31]), .a(rnd[i + 1]), .b(rnd[i]), .y(man[i]));
        end
        for (i = 0; i < 8; i = i + 1) begin : g_fl
            ot_psf_mx1 u_mx21 (.s(cy[((23 + i) * RC) / 31]), .a(r6_fb[i]), .b(r6_fa[i]), .y(field[i]));
        end
    endgenerate
    wire ovh0 = !r6_sub[0] && (cy[0] ? r6_ob[0] : r6_oa[0]);
    wire ovh1 = !r6_sub[OC-1] && (cy[RC-1] ? r6_ob[1] : r6_oa[1]);
    // code: sub -> {7'b0, rnd[23:0]} (a round carry out of a subnormal is the field-1 code), else {field, man}
    wire [30:0] cn = {field, man};
    wire [30:0] cs = {7'd0, rnd};
    (* keep *) wire [30:0] code;
    generate for (i = 0; i < 31; i = i + 1) begin : g_c
        ot_psf_mx1 u_mx22 (.s(r6_sub[(i * OC) / 31]), .a(cs[i]), .b(cn[i]), .y(code[i]));
    end endgenerate
    wire k0 = r6_byp[0] || ovh0, k1 = r6_byp[BC-1] || ovh1;
    wire [31:0] yn;
    generate for (i = 0; i < 31; i = i + 1) begin : g_y
        assign yn[i] = !((i < 16) ? k0 : k1) && code[i];
    end endgenerate
    assign yn[31] = !k1 && (code != 31'd0) && r6_sign;
    always @(posedge clk or negedge rst_n) if (!rst_n) valid_out <= 1'b0; else valid_out <= r6_v;
    always @(posedge clk) begin
        y <= yn;
        err <= r6_byp[BC-1] ? r6_err : (ovh1 ? 2'd2 : 2'd0);
    end
endmodule

// =====================================================================================================================
// binary32 divide, bit for bit ot_dsrom_su_fdiv_f12 (RNE, canonical +0, a zero dividend -> +0, a zero divisor /
// nonfinite / overflow -> 0 with a fault on the output edge).  Non-restoring steps (the existing NR 1 quotient), one-hot
// pre-normalise and denormal shift, kept copies of every wide select.  DEPTH 35 (P1, N, D, 27 steps, X, F1, F2, F3, Y).
// =====================================================================================================================
module ot_psf_div (
    input  wire clk, input wire rst_n, input wire v, input wire [31:0] a, input wire [31:0] b,
    (* keep *) output reg [31:0] y, output wire vo, output wire vpre, (* keep *) output reg fault
);
    localparam integer QB = 27, DEPTH = 35;
    localparam integer QC = 4 * `PSF_X, FC = 4 * `PSF_X;
    genvar i, j, s;
    wire [DEPTH:0] vd;
    ot_psf_vline #(.D(DEPTH)) u_v (.clk(clk), .rst_n(rst_n), .v(v), .vd(vd));
    assign vo = vd[DEPTH];
    assign vpre = vd[DEPTH-1];
    function automatic [4:0] lzp(input [22:0] f);
        integer k; (* keep *) reg [4:0] p;
        begin p = 5'd0; for (k = 0; k < 23; k = k + 1) if (f[k]) p = k[4:0]; lzp = p; end
    endfunction
    // ------------------------------------------------------------ P1: significand with hidden bit, one-hot leading one
    wire [23:0] fa = {(a[30:23] != 8'd0), a[22:0]}, fb = {(b[30:23] != 8'd0), b[22:0]};
    wire [23:0] ha, hb;                                              // ha[k] = |fa[23:k]
    assign ha[23] = fa[23]; assign hb[23] = fb[23];
    generate for (i = 22; i >= 0; i = i - 1) begin : g_h
        assign ha[i] = ha[i+1] | fa[i]; assign hb[i] = hb[i+1] | fb[i];
    end endgenerate
    (* keep *) reg [23:0] p1_fa, p1_fb, p1_oa, p1_ob; (* keep *) reg [9:0] p1_ea, p1_eb; (* keep *) reg p1_sign, p1_zero, p1_bad;
    always @(posedge clk) begin
        p1_fa <= fa; p1_fb <= fb;
        p1_ea <= (a[30:23] != 8'd0) ? {2'd0, a[30:23]} - 10'd127 : {5'd0, lzp(a[22:0])} - 10'd149;
        p1_eb <= (b[30:23] != 8'd0) ? {2'd0, b[30:23]} - 10'd127 : {5'd0, lzp(b[22:0])} - 10'd149;
        p1_sign <= a[31] ^ b[31];
        p1_zero <= (a[30:0] == 31'd0);
        p1_bad <= (a[30:23] == 8'hFF) || (b[30:23] == 8'hFF) || (b[30:0] == 31'd0);
    end
    generate for (i = 0; i < 24; i = i + 1) begin : g_lo
        always @(posedge clk) begin
            p1_oa[i] <= (i == 0) ? !ha[1] : (i == 23) ? fa[23] : (fa[i] && !ha[i+1]);
            p1_ob[i] <= (i == 0) ? !hb[1] : (i == 23) ? fb[23] : (fb[i] && !hb[i+1]);
        end
    end endgenerate
    // ------------------------------------------------------------ N: sig = F << (23 - leading position)
    wire [23:0] sa, sb;
    generate for (j = 0; j < 24; j = j + 1) begin : g_ns
        wire [23:0] ta, tb;
        for (i = 0; i < 24; i = i + 1) begin : g_t
            if (j - 23 + i >= 0) begin : g_in
                assign ta[i] = p1_oa[i] & p1_fa[j - 23 + i];
                assign tb[i] = p1_ob[i] & p1_fb[j - 23 + i];
            end else begin : g_out
                assign ta[i] = 1'b0; assign tb[i] = 1'b0;
            end
        end
        assign sa[j] = |ta; assign sb[j] = |tb;
    end endgenerate
    (* keep *) reg n_sign, n_zero, n_bad; (* keep *) reg [23:0] n_ma, n_mb; (* keep *) reg [9:0] n_ea, n_eb;
    always @(posedge clk) begin
        n_sign <= p1_sign; n_zero <= p1_zero; n_bad <= p1_bad; n_ma <= sa; n_mb <= sb; n_ea <= p1_ea; n_eb <= p1_eb;
    end
    (* keep *) reg d_sign, d_zero, d_bad; (* keep *) reg [23:0] d_ma, d_mb; (* keep *) reg signed [10:0] d_e;
    always @(posedge clk) begin
        d_sign <= n_sign; d_zero <= n_zero; d_bad <= n_bad; d_ma <= n_ma; d_mb <= n_mb;
        d_e <= $signed({n_ea[9], n_ea}) - $signed({n_eb[9], n_eb});
    end
    // ------------------------------------------------------------ steps (non-restoring, signed partial remainder)
    (* keep *) reg [26:0]        p_rem [0:QB-1];
    (* keep *) reg [QB-1:0]      r_q   [0:QB-1];
    (* keep *) reg [23:0]        r_mb  [0:QB-1];
    (* keep *) reg               r_sign [0:QB-1], r_zero [0:QB-1], r_bad [0:QB-1];
    (* keep *) reg signed [10:0] r_e   [0:QB-1];
    (* keep *) reg [3*QB-1:0] qcs;                                   // kept copies of each step's quotient bit
    generate for (j = 0; j < QB; j = j + 1) begin : g_rec
        wire [23:0] mb = (j == 0) ? d_mb : r_mb[(j == 0) ? 0 : j-1];
        wire [QB-1:0] qin = (j == 0) ? {QB{1'b0}} : r_q[(j == 0) ? 0 : j-1];
        wire [2:0] sub;
        if (j == 0) begin : g_s0
            assign sub = 3'b111;
        end else begin : g_sn
            assign sub = qcs[3 * ((j == 0) ? 0 : j-1) +: 3];
        end
        wire [26:0] x = (j == 0) ? {3'b0, d_ma} : {p_rem[(j == 0) ? 0 : j-1][25:0], 1'b0};
        wire [26:0] opb;
        for (i = 0; i < 24; i = i + 1) begin : g_ob
            assign opb[i] = sub[(i < 12) ? 0 : 1] ^ mb[i];
        end
        assign opb[26:24] = {3{sub[2]}};
        wire [26:0] p; wire unused_c;
        ot_psf_ks #(.W(27)) u_as (.a(x), .b(opb), .cin(sub[2]), .s(p), .cout(unused_c));
        always @(posedge clk) begin
            p_rem[j] <= p; r_q[j] <= {qin[QB-2:0], !p[26]}; qcs[3*j +: 3] <= {3{!p[26]}};
            r_mb[j] <= mb;
            r_sign[j] <= (j == 0) ? d_sign : r_sign[(j == 0) ? 0 : j-1];
            r_zero[j] <= (j == 0) ? d_zero : r_zero[(j == 0) ? 0 : j-1];
            r_bad[j]  <= (j == 0) ? d_bad  : r_bad[(j == 0) ? 0 : j-1];
            r_e[j]    <= (j == 0) ? d_e    : r_e[(j == 0) ? 0 : j-1];
        end
    end endgenerate
    wire [26:0] pl = p_rem[QB-1];
    wire [26:0] ml = {3'b0, r_mb[QB-1]};
    wire pz = (pl == 27'd0);
    wire pmz = ((pl ^ ml) == {pl[25:0] | ml[25:0], 1'b0});
    (* keep *) reg [QB-1:0] x_q; (* keep *) reg x_sign, x_zero, x_bad, x_nz; (* keep *) reg signed [10:0] x_e;
    (* keep *) reg [QC-1:0] x_q26;
    always @(posedge clk) begin
        x_q <= r_q[QB-1]; x_sign <= r_sign[QB-1]; x_zero <= r_zero[QB-1]; x_bad <= r_bad[QB-1]; x_e <= r_e[QB-1];
        x_nz <= r_q[QB-1][0] ? !pz : !pmz; x_q26 <= {QC{r_q[QB-1][26]}};
    end
    // ------------------------------------------------------------ F1: normalise by q[26] (copies), one-hot denormal shift
    // q26 selects: sig 24 | g | st = 26 over QC copies
    wire [23:0] sig; wire g, stk;
    generate for (i = 0; i < 24; i = i + 1) begin : g_sig
        ot_psf_mx1 u_mx23 (.s(x_q26[(i * QC) / 26]), .a(x_q[i + 3]), .b(x_q[i + 2]), .y(sig[i]));
    end endgenerate
    ot_psf_mx1 u_mx24 (.s(x_q26[(24 * QC) / 26]), .a(x_q[2]), .b(x_q[1]), .y(g));
    assign stk = x_q26[(25 * QC) / 26] ? ((|x_q[1:0]) || x_nz) : (x_q[0] || x_nz);
    wire signed [10:0] be1 = x_e + 11'sd126 + {10'd0, x_q26[QC-1]};
    wire signed [10:0] sh_full = 11'sd1 - be1;
    wire sub1 = (be1 < 11'sd1);
    (* keep *) reg f1_sign, f1_zero, f1_bad, f1_g, f1_st, f1_ovf; (* keep *) reg [23:0] f1_sig; (* keep *) reg [7:0] f1_field; (* keep *) reg [25:0] f1_oh;
    (* keep *) reg [FC-1:0] f1_sub;
    always @(posedge clk) begin
        f1_sign <= x_sign; f1_zero <= x_zero; f1_bad <= x_bad; f1_sig <= sig; f1_g <= g; f1_st <= stk;
        f1_sub <= {FC{sub1}}; f1_ovf <= (be1 > 11'sd254); f1_field <= be1[7:0];
    end
    // f1_sh = min(sh_full, 25) (the original's unsigned clamp: a negative sh_full reads as > 25)
    wire [4:0] shc = (sh_full[10] || (sh_full > 11'sd24)) ? 5'd25 : sh_full[4:0];
    wire [25:0] f1oh_w;
    ot_psf_oh5 #(.N(26)) u_f1oh (.en(1'b1), .x(shc), .oh(f1oh_w));
    always @(posedge clk) f1_oh <= f1oh_w;
    // ------------------------------------------------------------ F2
    wire [24:0] ext = {f1_sig, f1_g};
    wire [24:0] epre;
    assign epre[0] = ext[0];
    generate for (i = 1; i < 25; i = i + 1) begin : g_ep
        assign epre[i] = epre[i-1] | ext[i];
    end endgenerate
    wire [24:0] esh;
    generate for (i = 0; i < 25; i = i + 1) begin : g_es
        wire [25:0] t;
        for (s = 0; s < 26; s = s + 1) begin : g_t
            if (i + s < 25) begin : g_in
                assign t[s] = f1_oh[s] & ext[i + s];
            end else begin : g_out
                assign t[s] = 1'b0;
            end
        end
        assign esh[i] = |t;
    end endgenerate
    wire [25:0] tl;
    generate for (s = 0; s < 26; s = s + 1) begin : g_tl
        if (s == 0) begin : g_0
            assign tl[0] = 1'b0;
        end else begin : g_n
            assign tl[s] = f1_oh[s] & epre[s - 1];
        end
    end endgenerate
    wire lost = |tl;
    // f1_sub selects: sig 24 | g | st | field 8 = 34 over FC copies
    wire [23:0] sig2; wire g2, st2; wire [7:0] fld2;
    generate
        for (i = 0; i < 24; i = i + 1) begin : g_s2
            ot_psf_mx1 u_mx25 (.s(f1_sub[(i * FC) / 34]), .a(esh[i + 1]), .b(f1_sig[i]), .y(sig2[i]));
        end
        for (i = 0; i < 8; i = i + 1) begin : g_f2
            assign fld2[i] = !f1_sub[((26 + i) * FC) / 34] && f1_field[i];
        end
    endgenerate
    ot_psf_mx1 u_mx26 (.s(f1_sub[(24 * FC) / 34]), .a(esh[0]), .b(f1_g), .y(g2));
    assign st2 = f1_st || (f1_sub[(25 * FC) / 34] && lost);
    (* keep *) reg f2_sign, f2_zero, f2_bad, f2_ovf, f2_g, f2_st; (* keep *) reg [23:0] f2_sig; (* keep *) reg [7:0] f2_field;
    always @(posedge clk) begin
        f2_sign <= f1_sign; f2_zero <= f1_zero; f2_bad <= f1_bad; f2_ovf <= f1_ovf;
        f2_sig <= sig2; f2_g <= g2; f2_st <= st2; f2_field <= fld2;
    end
    // ------------------------------------------------------------ F3: round increment; overflow of the rounded code
    wire rinc = f2_g && (f2_st || f2_sig[0]);
    wire [30:0] code_inc; wire code_co;
    ot_psf_inc #(.W(31)) u_rnd (.a({f2_field, f2_sig[22:0]}), .inc(rinc), .y(code_inc), .co(code_co));
    wire ovf_all = f2_ovf || (code_inc[30:23] == 8'hFF);
    (* keep *) reg f3_sign; (* keep *) reg [30:0] f3_code; (* keep *) reg f3_flt;
    (* keep *) reg [1:0] f3_kill;
    always @(posedge clk) begin
        f3_sign <= f2_sign; f3_code <= code_inc;
        f3_kill <= {2{f2_bad || ovf_all || f2_zero}};
        f3_flt <= f2_bad || (ovf_all && !f2_zero);
    end
    // ------------------------------------------------------------ Y
    wire [31:0] yn;
    generate for (i = 0; i < 31; i = i + 1) begin : g_y
        assign yn[i] = !f3_kill[i / 16] && f3_code[i];
    end endgenerate
    assign yn[31] = !f3_kill[1] && (f3_code != 31'd0) && f3_sign;
    always @(posedge clk) begin
        y <= yn;
        fault <= f3_flt && vd[DEPTH-1];
    end
endmodule

// =====================================================================================================================
// exp(x), bit for bit ot_hdc_v41x_exp: clamp to [-87, 88], n = rint(x log2e), {n LN2_HI, RN(n LN2_LO)} from the
// table, two-constant reduction, degree-6 Horner, 2^n into the exponent field.  Pool-local units (ot_psf_add LA,
// ot_psf_mul LM).  +2 edges: the clamp select is a registered flag with copies (T_C = 2); the table is a registered
// one-hot (hi, lo nibble) decode with one kept copy per TB output bits (T_K = T_N + 2).  DEPTH = 7 LM + 8 LA + 6.
// =====================================================================================================================
module ot_psf_exp #(parameter integer LM = 7, parameter integer LA = 6) (
    input  wire clk, input wire rst_n, input wire v, input wire [31:0] x,
    (* keep *) output reg [31:0] y, output wire vo, output wire vpre, output wire fault
);
    localparam integer T_C = 2;
    localparam integer T_N = T_C + LM + 1;
    localparam integer T_K = T_N + 2;
    localparam integer T_R1 = T_K + LA;
    localparam integer T_R = T_R1 + LA;
    localparam integer T_P = T_R + 6 * (LM + LA);
    localparam integer DEPTH = T_P + 1;
    localparam [31:0] K_MAX = 32'h42B00000, K_MINM = 32'h42AE0000, K_LOG2E = 32'h3FB8AA3B;
    localparam [32*7-1:0] POLY = {32'h3AB60B61, 32'h3C088889, 32'h3D2AAAAB,
                                  32'h3E2AAAAB, 32'h3F000000, 32'h3F800000, 32'h3F800000};
    localparam integer NC = 8;                                       // nint copies
    localparam integer TB = `PSF_TB;                                 // table output bits per kept decode copy
    localparam integer NG = 64 / TB;
    genvar i, k;
    // the reset leaves: line, the 15 units
    wire [15:0] rl;
    ot_psf_rtree #(.N(16)) u_rt (.clk(clk), .rst_n(rst_n), .q(rl));
    wire [DEPTH:0] vd;
    ot_psf_vline #(.D(DEPTH)) u_v (.clk(clk), .rst_n(rl[0]), .v(v), .vd(vd));
    assign vo = vd[DEPTH];
    assign vpre = vd[DEPTH-1];
    // ---- depth 1: x and the clamp flags (copies); depth 2: xc
    (* keep *) reg [31:0] x_r;
    (* keep *) reg [3:0] c_hi, c_lo;
    always @(posedge clk) begin
        x_r <= x;
        c_hi <= {4{!x[31] && (x[30:0] > K_MAX[30:0])}};
        c_lo <= {4{x[31] && (x[30:0] > K_MINM[30:0])}};
    end
    (* keep *) reg [31:0] xc;
    generate for (i = 0; i < 32; i = i + 1) begin : g_xc
        always @(posedge clk) xc[i] <= c_hi[i / 8] ? K_MAX[i] : (c_lo[i / 8] ? ((i == 31) ? 1'b1 : K_MINM[i]) : x_r[i]);
    end endgenerate
    wire [31:0] t;
    wire [2:0] f;
    wire [1:0] e_t; wire v_t;
    ot_psf_mul m_t (.clk(clk), .rst_n(rl[1]), .valid_in(vd[T_C]), .a(xc), .b(K_LOG2E), .y(t), .err(e_t), .valid_out(v_t));
    // ---- depth T_N: n = rint-to-even(t) by a one-hot integer-part select (E = te - 127 in [-1, 6] <=> te in [126, 133])
    wire [23:0] tm = {1'b1, t[22:0]};
    wire [7:0]  te = t[30:23];
    wire [7:0]  eo;                                                  // eo[e] : te == 126 + e (tsh = 24 - e)
    wire [7:0]  teo = te - 8'd126;
    wire [31:0] eo_w;
    ot_psf_oh5 #(.N(32)) u_eo (.en(teo[7:5] == 3'd0), .x(teo[4:0]), .oh(eo_w));
    assign eo = eo_w[7:0];
    wire [23:0] tpre;
    assign tpre[0] = tm[0];
    generate for (i = 1; i < 24; i = i + 1) begin : g_tp
        assign tpre[i] = tpre[i-1] | tm[i];
    end endgenerate
    wire [7:0] tip;
    generate for (k = 0; k < 8; k = k + 1) begin : g_tip
        wire [7:0] tt;
        for (i = 0; i < 8; i = i + 1) begin : g_t
            if (k + 24 - i <= 23) begin : g_in
                assign tt[i] = eo[i] & tm[k + 24 - i];
            end else begin : g_out
                assign tt[i] = 1'b0;
            end
        end
        assign tip[k] = |tt;
    end endgenerate
    wire [7:0] th, ts;
    generate for (i = 0; i < 8; i = i + 1) begin : g_hs
        assign th[i] = eo[i] & tm[23 - i];                           // tm[trb], trb = tsh - 1 = 23 - e
        assign ts[i] = eo[i] & tpre[22 - i];                         // |tm[trb-1:0]
    end endgenerate
    wire thalf = |th, tstk = |ts;
    wire [7:0] tmag = tip + {7'd0, thalf && (tstk || tip[0])};
    wire [8:0] nint_w = t[31] ? -{1'b0, tmag} : {1'b0, tmag};
    (* keep *) reg [8:0] nint;
    (* keep *) reg [8*NC-1:0] nk;
    always @(posedge clk) begin nint <= nint_w; nk <= {NC{nint_w[7:0]}}; end
    // ---- depth T_N + 1: one-hot (hi, lo) nibble decode, one kept copy per group
    wire [64*256-1:0] tbits;
    ot_psf_ln2_bits u_bits (.b(tbits));
    wire [63:0] ahl;
    generate for (k = 0; k < NG; k = k + 1) begin : g_grp
        wire [7:0] n = nk[8 * ((k * NC) / NG) +: 8];
        (* keep *) wire [3:0] pl0, pl1, ph0, ph1;                    // 2-bit predecodes
        for (i = 0; i < 4; i = i + 1) begin : g_pd
            assign pl0[i] = (n[1:0] == i); assign pl1[i] = (n[3:2] == i);
            assign ph0[i] = (n[5:4] == i); assign ph1[i] = (n[7:6] == i);
        end
        (* keep *) reg [15:0] lo, hi;
        for (i = 0; i < 16; i = i + 1) begin : g_oh
            always @(posedge clk) begin lo[i] <= pl0[i % 4] & pl1[i / 4]; hi[i] <= ph0[i % 4] & ph1[i / 4]; end
        end
        for (i = 0; i < TB; i = i + 1) begin : g_b
            wire [255:0] col = tbits[256 * (k * TB + i) +: 256];
            wire [15:0] gh;
            genvar h;
            for (h = 0; h < 16; h = h + 1) begin : g_h
                assign gh[h] = hi[h] & (|(lo & col[16 * h +: 16]));
            end
            (* keep *) reg q;
            always @(posedge clk) q <= |gh;
            assign ahl[k * TB + i] = q;
        end
    end endgenerate
    wire [31:0] a_hi = ahl[63:32], a_lo = ahl[31:0];
    // ---- reduction and Horner (unchanged structure)
    wire [31:0] r1, r, xc_d, lo_d;
    ot_psf_delay #(.W(32), .D(T_K - T_C)) d_x (.clk(clk), .d(xc), .q(xc_d));
    wire [1:0] e_r1, e_r;
    wire v_r1, v_r;
    ot_psf_add a_r1 (.clk(clk), .rst_n(rl[2]), .valid_in(vd[T_K]), .a(xc_d), .b({~a_hi[31], a_hi[30:0]}), .y(r1),
                     .err(e_r1), .valid_out(v_r1));
    ot_psf_delay #(.W(32), .D(LA)) d_lo (.clk(clk), .d(a_lo), .q(lo_d));
    ot_psf_add a_r (.clk(clk), .rst_n(rl[3]), .valid_in(vd[T_R1]), .a(r1), .b({~lo_d[31], lo_d[30:0]}), .y(r),
                    .err(e_r), .valid_out(v_r));
    wire [31:0] rd [0:6];
    wire [31:0] pm [1:6];
    wire [31:0] pa [0:6];
    wire [12:1] hf;
    assign rd[0] = r;
    assign pa[0] = POLY[32*6 +: 32];
    generate for (k = 1; k <= 6; k = k + 1) begin : g_h
        if (k < 6) begin : g_rd
            ot_psf_delay #(.W(32), .D(LM + LA)) d_r (.clk(clk), .d(rd[k-1]), .q(rd[k]));
        end
        wire [1:0] em, ea; wire vm, va;
        ot_psf_mul u_m (.clk(clk), .rst_n(rl[3 + k]), .valid_in(vd[T_R + (LM + LA)*(k-1)]), .a(pa[k-1]), .b(rd[k-1]),
                        .y(pm[k]), .err(em), .valid_out(vm));
        ot_psf_add u_a (.clk(clk), .rst_n(rl[9 + k]), .valid_in(vd[T_R + (LM + LA)*(k-1) + LM]), .a(pm[k]),
                        .b(POLY[32*(6-k) +: 32]), .y(pa[k]), .err(ea), .valid_out(va));
        assign hf[2*k-1] = vm && (em != 2'd0);
        assign hf[2*k] = va && (ea != 2'd0);
    end endgenerate
    assign f[0] = v_t && (e_t != 2'd0);
    assign f[1] = v_r1 && (e_r1 != 2'd0);
    assign f[2] = v_r && (e_r != 2'd0);
    wire [8:0] nint_d;
    ot_psf_delay #(.W(9), .D(T_P - T_N)) d_n (.clk(clk), .d(nint), .q(nint_d));
    wire [31:0] y_n; wire unused_cy;
    ot_psf_ks #(.W(32)) u_yn (.a(pa[6]), .b({nint_d, 23'd0}), .cin(1'b0), .s(y_n), .cout(unused_cy));
    always @(posedge clk) y <= y_n;
    assign fault = |{f, hf};
endmodule

// {n LN2_HI, RN(n LN2_LO)} by the low 8 bits of n (from ot_hdc_v41x_sfu.sv ln2_nk, default 0): bit
// 256 b + k = bit b of entry k
module ot_psf_ln2_bits (output wire [64*256-1:0] b);
    assign b = 16384';
endmodule


// =====================================================================================================================
// pool lane (one FP32 feature): the calendar of ot_s81sl_cmp_pool_lane with the pool-local units; every hold / select
// of a 32-bit word is cut into 8 groups of 4 bits, each on its own pre-registered enable / select copy.
// =====================================================================================================================
module ot_s81sl_cmp_pool_lane #(
    parameter integer LM = 7, LA = 6, MUT = 0
) (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        i_v,
    input  wire [1:0]  i_role,
    input  wire [31:0] i_d,
    (* keep *) output reg         o_v,
    (* keep *) output reg  [31:0] o_y,
    (* keep *) output reg  [31:0] o_y32,
    (* keep *) output reg         fault
);
    localparam integer G = 8;                                         // 4-bit groups of a word
    genvar g, k;
    wire [23:0] rl;
    ot_psf_rtree #(.N(24)) u_rt (.clk(clk), .rst_n(rst_n), .q(rl));
    wire rn = rl[0];
    function automatic gt;                                           // binary32 a > b (sign-magnitude order)
        input [31:0] a, b;
        begin
            if (a[30:0] == 31'd0 && b[30:0] == 31'd0) gt = 1'b0;
            else if (a[31] != b[31]) gt = !a[31];
            else if (!a[31]) gt = a[30:0] > b[30:0];
            else gt = a[30:0] < b[30:0];
        end
    endfunction
    function automatic [31:0] bf16;
        input [31:0] x;
        (* keep *) reg [32:0] s;
        begin
            s = {1'b0, x} + 33'h7FFF + {32'd0, x[16]};
            bf16 = {s[31:16], 16'd0};
        end
    endfunction
    // pin flops (+ per-group copies of the valid / role for the hold enables)
    (* keep *) reg v_q; (* keep *) reg [1:0] r_q; (* keep *) reg [31:0] d_q;
    (* keep *) reg [G-1:0] vg;
    (* keep *) reg [2*G-1:0] rg;
    always @(posedge clk) begin r_q <= i_role; d_q <= i_d; vg <= {G{i_v}}; rg <= {G{i_role}}; end
    always @(posedge clk or negedge rn) if (!rn) v_q <= 1'b0; else v_q <= i_v;
    wire sc0 = v_q && r_q == 2'd0, sc1 = v_q && r_q == 2'd1, kv0 = v_q && r_q == 2'd2, kv1 = v_q && r_q == 2'd3;
    wire [G-1:0] sc0g, sc1g, kv0g;
    generate for (g = 0; g < G; g = g + 1) begin : g_dec
        assign sc0g[g] = vg[g] && (rg[2*g +: 2] == 2'd0);
        assign sc1g[g] = vg[g] && (rg[2*g +: 2] == 2'd1);
        assign kv0g[g] = vg[g] && (rg[2*g +: 2] == 2'd2);
    end endgenerate
    // ---------------------------------------------------------------- max: kept compare flag, held operands
    (* keep *) reg [31:0] s0, s0h, s1h;
    (* keep *) reg [G-1:0] gtc;
    (* keep *) reg av, av1;
    (* keep *) reg [G-1:0] avc;
    wire gtw = (MUT != 4) && gt(d_q, s0);
    generate for (g = 0; g < G; g = g + 1) begin : g_mx
        always @(posedge clk) begin
            if (sc0g[g]) s0[4*g +: 4] <= d_q[4*g +: 4];
            if (sc1g[g]) begin s0h[4*g +: 4] <= s0[4*g +: 4]; s1h[4*g +: 4] <= d_q[4*g +: 4]; gtc[g] <= gtw; end
            avc[g] <= sc1g[g];
        end
    end endgenerate
    always @(posedge clk or negedge rn) if (!rn) begin av <= 1'b0; av1 <= 1'b0; end else begin av <= sc1; av1 <= av; end
    // ---------------------------------------------------------------- sub (one adder, two items)
    wire sv = av || av1;
    wire [31:0] sa, nmx;
    generate for (g = 0; g < G; g = g + 1) begin : g_sa
        for (k = 0; k < 4; k = k + 1) begin : g_b
            ot_psf_mx1 u_sa (.s(avc[g]), .a(s0h[4*g + k]), .b(s1h[4*g + k]), .y(sa[4*g + k]));
            ot_psf_mx1 u_nm (.s(gtc[g]), .a(s1h[4*g + k]), .b(s0h[4*g + k]), .y(nmx[4*g + k]));
        end
    end endgenerate
    wire [31:0] sd; wire [1:0] s_e; wire s_vo;
    ot_psf_add u_sub (.clk(clk), .rst_n(rl[1]), .valid_in(sv), .a(sa), .b({~nmx[31], nmx[30:0]}), .y(sd), .err(s_e),
                      .valid_out(s_vo));
    wire sf = s_vo && (s_e != 2'd0);
    wire [LA:0] svd;
    ot_psf_vline #(.D(LA)) u_svd (.clk(clk), .rst_n(rl[2]), .v(sv), .vd(svd));
    // ---------------------------------------------------------------- exp
    wire ev, epre; wire [31:0] ey; wire ef;
    ot_psf_exp #(.LM(LM), .LA(LA)) u_exp (.clk(clk), .rst_n(rl[3]), .v(svd[LA]), .x(sd), .y(ey), .vo(ev), .vpre(epre),
                                         .fault(ef));
    (* keep *) reg ev_d; (* keep *) reg [31:0] e0h;
    (* keep *) reg [G-1:0] e0en;                                     // = ev && !ev_d, one edge ahead
    always @(posedge clk or negedge rn) if (!rn) ev_d <= 1'b0; else ev_d <= ev;
    always @(posedge clk) e0en <= {G{epre && !ev}};
    wire e_item1 = ev && ev_d;
    generate for (g = 0; g < G; g = g + 1) begin : g_e0
        always @(posedge clk) if (e0en[g]) e0h[4*g +: 4] <= ey[4*g +: 4];
    end endgenerate
    // ---------------------------------------------------------------- den = e0 + e1 (MUT 1: e0 + e0)
    wire [31:0] den; wire [1:0] d_e; wire d_vo;
    ot_psf_add u_den (.clk(clk), .rst_n(rl[4]), .valid_in(e_item1), .a(e0h), .b((MUT == 1) ? e0h : ey), .y(den),
                      .err(d_e), .valid_out(d_vo));
    wire df = d_vo && (d_e != 2'd0);
    wire [LA:0] dvd;
    ot_psf_vline #(.D(LA)) u_dvd (.clk(clk), .rst_n(rl[5]), .v(e_item1), .vd(dvd));
    (* keep *) reg [G-1:0] dvc;                                      // copies of dvd[LA]
    always @(posedge clk) dvc <= {G{dvd[LA-1]}};
    wire [31:0] ed; wire [LA+1:0] edl;
    ot_psf_delay #(.W(32), .D(LA + 1)) u_ed (.clk(clk), .d(ey), .q(ed));
    ot_psf_vline #(.D(LA + 1)) u_edv (.clk(clk), .rst_n(rl[6]), .v(ev), .vd(edl));
    wire edv = edl[LA+1];
    (* keep *) reg [31:0] denh; (* keep *) reg dh_v;
    wire [31:0] dsel;
    generate for (g = 0; g < G; g = g + 1) begin : g_dn
        always @(posedge clk) if (dvc[g]) denh[4*g +: 4] <= den[4*g +: 4];
        for (k = 0; k < 4; k = k + 1) begin : g_b
            ot_psf_mx1 u_ds (.s(dvc[g]), .a(den[4*g + k]), .b(denh[4*g + k]), .y(dsel[4*g + k]));
        end
    end endgenerate
    always @(posedge clk or negedge rn) if (!rn) dh_v <= 1'b0; else dh_v <= dvd[LA];
    // ---------------------------------------------------------------- p_i = e_i / den
    wire pv, ppre; wire [31:0] py; wire pf;
    ot_psf_div u_div (.clk(clk), .rst_n(rl[7]), .v(edv), .a(ed), .b(dsel), .y(py), .vo(pv), .vpre(ppre), .fault(pf));
    (* keep *) reg pv_d; (* keep *) reg [31:0] p0h, p1h; (* keep *) reg p0f, p1f;
    (* keep *) reg [G-1:0] p0en, p1en;
    always @(posedge clk or negedge rl[8]) if (!rl[8]) pv_d <= 1'b0; else pv_d <= pv;
    always @(posedge clk) begin p0en <= {G{ppre && !pv}}; p1en <= {G{ppre && pv}}; end
    generate for (g = 0; g < G; g = g + 1) begin : g_p
        always @(posedge clk) begin
            if (p0en[g]) p0h[4*g +: 4] <= py[4*g +: 4];
            if (p1en[g]) p1h[4*g +: 4] <= py[4*g +: 4];
        end
    end endgenerate
    // ---------------------------------------------------------------- products kv_i * p_i (one multiplier), y = m0 + m1
    wire mv = kv0 || kv1;
    wire [31:0] mb;
    generate for (g = 0; g < G; g = g + 1) begin : g_mb
        for (k = 0; k < 4; k = k + 1) begin : g_b
            ot_psf_mx1 u_mb (.s(kv0g[g]), .a((MUT == 2) ? p1h[4*g + k] : p0h[4*g + k]),
                             .b((MUT == 2) ? p0h[4*g + k] : p1h[4*g + k]), .y(mb[4*g + k]));
        end
    end endgenerate
    wire [31:0] my; wire [1:0] m_e; wire m_vo;
    ot_psf_mul u_mul (.clk(clk), .rst_n(rl[9]), .valid_in(mv), .a(d_q), .b(mb), .y(my), .err(m_e), .valid_out(m_vo));
    wire mf = m_vo && (m_e != 2'd0);
    wire [LM:0] mvd;
    ot_psf_vline #(.D(LM)) u_mvd (.clk(clk), .rst_n(rl[10]), .v(mv), .vd(mvd));
    (* keep *) reg mvd_d; (* keep *) reg [31:0] m0h;
    (* keep *) reg [G-1:0] m0en;
    always @(posedge clk or negedge rl[8]) if (!rl[8]) mvd_d <= 1'b0; else mvd_d <= mvd[LM];
    always @(posedge clk) m0en <= {G{mvd[LM-1] && !mvd[LM]}};
    wire m_item1 = mvd[LM] && mvd_d;
    generate for (g = 0; g < G; g = g + 1) begin : g_m0
        always @(posedge clk) if (m0en[g]) m0h[4*g +: 4] <= my[4*g +: 4];
    end endgenerate
    wire [31:0] yy; wire [1:0] y_e; wire y_vo;
    ot_psf_add u_fin (.clk(clk), .rst_n(rl[11]), .valid_in(m_item1), .a(m0h), .b(my), .y(yy), .err(y_e),
                      .valid_out(y_vo));
    wire yf = y_vo && (y_e != 2'd0);
    wire [LA:0] yvd;
    ot_psf_vline #(.D(LA)) u_yvd (.clk(clk), .rst_n(rl[12]), .v(m_item1), .vd(yvd));
    (* keep *) reg [G-1:0] yvc;
    always @(posedge clk) yvc <= {G{yvd[LA-1]}};
    wire [31:0] ybf = (MUT == 3) ? {yy[31:16], 16'd0} : bf16(yy);
    generate for (g = 0; g < G; g = g + 1) begin : g_o
        always @(posedge clk) if (yvc[g]) begin o_y[4*g +: 4] <= ybf[4*g +: 4]; o_y32[4*g +: 4] <= yy[4*g +: 4]; end
    end endgenerate
    // ---------------------------------------------------------------- valid / fault
    always @(posedge clk or negedge rl[13]) begin
        if (!rl[13]) begin o_v <= 1'b0; fault <= 1'b0; p0f <= 1'b0; p1f <= 1'b0; end
        else begin
            o_v <= yvd[LA];
            if (pv && !pv_d) begin if (p0f) fault <= 1'b1; p0f <= 1'b1; end
            else if (kv0) begin if (!p0f) fault <= 1'b1; p0f <= 1'b0; end
            if (pv && pv_d) begin if (p1f) fault <= 1'b1; p1f <= 1'b1; end
            else if (kv1) begin if (!p1f) fault <= 1'b1; p1f <= 1'b0; end
            if ((pv && !pv_d && kv0) || (pv && pv_d && kv1)) fault <= 1'b1;
            if (sf || ef || df || pf || mf || yf) fault <= 1'b1;
        end
    end
endmodule

// =====================================================================================================================
// pool top: ports, command check, static issue calendar and tag queue of ot_s81sl_cmp_pool; the calendar constants
// carry the pool-local unit latencies (LM 7, LA 6, DE = 7 LM + 8 LA + 6, DD = 35).  Kept copies: busy (4), issue
// edge (2), per-lane response valid / role registers; four reset leaves for the control groups.
// =====================================================================================================================
module ot_s81sl_cmp_pool #(
    parameter integer LM = 7, LA = 6, MUT = 0
) (
    input  wire         clk,            // control region root
    input  wire [7:0]   ck_l,           // lane region roots (one local tree per lane)
    input  wire         rst_n,
    input  wire         start,
    input  wire [9:0]   b0,
    input  wire [9:0]   b1,
    input  wire [9:0]   ob,
    output wire         busy,
    (* keep *) output reg          done,
    (* keep *) output reg          fault,
    (* keep *) output reg          x_rv,
    (* keep *) output reg  [9:0]   x_ra,
    input  wire         x_qv,
    input  wire [255:0] x_qd,
    (* keep *) output reg          x_wv,
    (* keep *) output reg  [9:0]   x_wa,
    (* keep *) output reg  [7:0]   x_wm,
    (* keep *) output reg  [255:0] x_wd,
    output wire [255:0] dbg_y32,
    output wire [15:0]  dbg_age
);
    localparam integer DE = 7 * LM + 8 * LA + 6;
    localparam integer DD = 35;
    localparam integer TP0 = 2 + LA + DE + 1 + LA + DD;
    localparam integer KLAG0 = (TP0 + 1 - 2 + 3) / 4;
    localparam integer KLAG = (MUT == 5) ? KLAG0 - 2 : KLAG0;
    localparam integer NG = 64;
    localparam integer NE = 4 * (NG + KLAG);
`ifndef SYNTHESIS
    initial if (MUT != 5 && (4 * KLAG + 2 < TP0 + 1 || 4 * KLAG + 2 > TP0 + 3))
        $fatal(1, "ot_s81sl_cmp_pool: no kv lag fits TP0 %0d", TP0);
`endif
    wire [15:0] rl;
    ot_psf_rtree #(.N(16)) u_rt (.clk(clk), .rst_n(rst_n), .q(rl));
    // busy copies: [0] port, [1] fault / done, [2] issue edge + issuing + read valid, [3] address issue edge,
    // [4] age, [5] tag pointers, [6] write side, [7] sb0, [8] sb1, [9] sob, [10] lane valids
    localparam integer NBZ = 11;
    (* keep *) reg [NBZ-1:0] bz;
    assign busy = bz[0];
    (* keep *) reg [9:0]  sb0, sb1, sob;
    (* keep *) reg [9:0] ie, iec;                                    // issue edge (calendar copy, address copy)
    (* keep *) reg [1:0] iss;                                        // issuing copies
    (* keep *) reg [15:0] age;
    (* keep *) reg [6:0]  nout;
    (* keep *) reg        fin;
    assign dbg_age = age;
    // ---------------------------------------------------------------- issue calendar (control copy)
    wire [7:0] ig = ie[9:2];
    wire [1:0] ij = ie[1:0];
    wire [7:0] kg = ig - KLAG[7:0];
    wire       sc_slot = (ij[1] == 1'b0) && (ig < NG);
    wire       kv_slot = (ij[1] == 1'b1) && (ig >= KLAG) && (kg < NG);
    // address copy
    wire [7:0] ag = iec[9:2];
    wire [1:0] aj = iec[1:0];
    wire [7:0] akg = ag - KLAG[7:0];
    wire       a_sc = (aj[1] == 1'b0) && (ag < NG);
    wire [7:0] gg = a_sc ? ag : akg;
    wire [9:0] rofs = {3'd0, gg[5:1], 2'b00} + {8'd0, gg[0], 1'b0};
    wire [9:0] rbase = aj[0] ? sb1 : sb0;
    wire [9:0] raddr = rbase + (a_sc ? 10'd128 : 10'd0) + rofs;
    // ---------------------------------------------------------------- tag queue
    (* keep *) reg [1:0] tq [0:7];
    (* keep *) reg [2:0] tw, tr; (* keep *) reg [3:0] tn;
    wire      push = iss[1] && (sc_slot || kv_slot);
    wire      pop  = x_qv;
    // ---------------------------------------------------------------- command check
    wire [10:0] x0 = {1'b0, b0}, x1 = {1'b0, b1}, xo = {1'b0, ob};
    wire [10:0] e0 = x0 + 11'd256, e1 = x1 + 11'd256, eo = xo + 11'd128;
    wire bad_cmd = (b0[1:0] != 2'd0) || (b1[1:0] != 2'd0) || (ob[1:0] != 2'd0) || (b0 > 10'd768) || (b1 > 10'd768) ||
                   (ob > 10'd896) || (b0 == b1) ||
                   ((x0 < x1) ? (e0 > x1) : (e1 > x0)) ||
                   !((ob == b0) || (ob == b1) || (((eo <= x0) || (xo >= e0)) && ((eo <= x1) || (xo >= e1))));
    wire [NBZ-1:0] go;                                               // command accepted, one copy per register group
    genvar l;
    generate for (l = 0; l < NBZ; l = l + 1) begin : g_go
        ot_psf_go u_go (.s(start), .bad(bad_cmd), .b(bz[l]), .y(go[l]));
    end endgenerate
    // ---------------------------------------------------------------- lanes (per-lane response valid / role registers)
    (* keep *) reg [7:0] l_v; (* keep *) reg [15:0] l_role; (* keep *) reg [255:0] l_d;
    wire [7:0] lo_v, lf;
    wire [255:0] lo_y, lo_y32;
    // REGIONAL CLOCK (RTLGAP-SUKV 10-22, SAFE 7): lane l = its own clock region on ck_l[l]; control <-> lane crossings
    // are fixed-latency landing rings (ot_s81_land D 4, K 1: 2 edges each way), cut in <= 8-bit chunks, one reset leaf per ring.
    wire [7:0] lif, lof;
    generate for (l = 0; l < 8; l = l + 1) begin : g_lane
        wire [5:0] lrs; wire [9-1:0] ors; wire [34:0] li_src = {l_v[l], l_role[2*l +: 2], l_d[32 * l +: 32]}; wire [34:0] li;
        wire o_v_r, f_r; wire [31:0] y_r, y32_r; wire [65:0] lo_src, lo_l;
        ot_psf_rtree #(.N(5 + 1)) u_lrs (.clk(ck_l[l]), .rst_n(rst_n), .q(lrs));
        ot_psf_rtree #(.N(9)) u_ors (.clk(clk), .rst_n(rst_n), .q(ors));
        wire [4:0] u_li_f;
        ot_s81_land #(.W(8), .D(4)) u_li0 (.k(3'd1), .ck_f(clk), .i(li_src[7:0]), .ck(ck_l[l]), .rs(lrs[0]), .o(li[7:0]), .fault(u_li_f[0]));
        ot_s81_land #(.W(8), .D(4)) u_li1 (.k(3'd1), .ck_f(clk), .i(li_src[15:8]), .ck(ck_l[l]), .rs(lrs[1]), .o(li[15:8]), .fault(u_li_f[1]));
        ot_s81_land #(.W(8), .D(4)) u_li2 (.k(3'd1), .ck_f(clk), .i(li_src[23:16]), .ck(ck_l[l]), .rs(lrs[2]), .o(li[23:16]), .fault(u_li_f[2]));
        ot_s81_land #(.W(8), .D(4)) u_li3 (.k(3'd1), .ck_f(clk), .i(li_src[31:24]), .ck(ck_l[l]), .rs(lrs[3]), .o(li[31:24]), .fault(u_li_f[3]));
        ot_s81_land #(.W(3), .D(4)) u_li4 (.k(3'd1), .ck_f(clk), .i(li_src[34:32]), .ck(ck_l[l]), .rs(lrs[4]), .o(li[34:32]), .fault(u_li_f[4]));
        assign lif[l] = |u_li_f;
        ot_s81sl_cmp_pool_lane #(.LM(LM), .LA(LA), .MUT(MUT)) u_l (
            .clk(ck_l[l]), .rst_n(lrs[5]), .i_v(li[34]), .i_role(li[33:32]), .i_d(li[31:0]),
            .o_v(o_v_r), .o_y(y_r), .o_y32(y32_r), .fault(f_r));
        assign lo_src = {o_v_r, f_r | lif[l], y_r, y32_r};
        wire [8:0] u_lo_f;
        ot_s81_land #(.W(8), .D(4)) u_lo0 (.k(3'd1), .ck_f(ck_l[l]), .i(lo_src[7:0]), .ck(clk), .rs(ors[0]), .o(lo_l[7:0]), .fault(u_lo_f[0]));
        ot_s81_land #(.W(8), .D(4)) u_lo1 (.k(3'd1), .ck_f(ck_l[l]), .i(lo_src[15:8]), .ck(clk), .rs(ors[1]), .o(lo_l[15:8]), .fault(u_lo_f[1]));
        ot_s81_land #(.W(8), .D(4)) u_lo2 (.k(3'd1), .ck_f(ck_l[l]), .i(lo_src[23:16]), .ck(clk), .rs(ors[2]), .o(lo_l[23:16]), .fault(u_lo_f[2]));
        ot_s81_land #(.W(8), .D(4)) u_lo3 (.k(3'd1), .ck_f(ck_l[l]), .i(lo_src[31:24]), .ck(clk), .rs(ors[3]), .o(lo_l[31:24]), .fault(u_lo_f[3]));
        ot_s81_land #(.W(8), .D(4)) u_lo4 (.k(3'd1), .ck_f(ck_l[l]), .i(lo_src[39:32]), .ck(clk), .rs(ors[4]), .o(lo_l[39:32]), .fault(u_lo_f[4]));
        ot_s81_land #(.W(8), .D(4)) u_lo5 (.k(3'd1), .ck_f(ck_l[l]), .i(lo_src[47:40]), .ck(clk), .rs(ors[5]), .o(lo_l[47:40]), .fault(u_lo_f[5]));
        ot_s81_land #(.W(8), .D(4)) u_lo6 (.k(3'd1), .ck_f(ck_l[l]), .i(lo_src[55:48]), .ck(clk), .rs(ors[6]), .o(lo_l[55:48]), .fault(u_lo_f[6]));
        ot_s81_land #(.W(8), .D(4)) u_lo7 (.k(3'd1), .ck_f(ck_l[l]), .i(lo_src[63:56]), .ck(clk), .rs(ors[7]), .o(lo_l[63:56]), .fault(u_lo_f[7]));
        ot_s81_land #(.W(2), .D(4)) u_lo8 (.k(3'd1), .ck_f(ck_l[l]), .i(lo_src[65:64]), .ck(clk), .rs(ors[8]), .o(lo_l[65:64]), .fault(u_lo_f[8]));
        assign lof[l] = |u_lo_f;
        assign lo_v[l] = lo_l[65]; assign lf[l] = lo_l[64] | lof[l];
        assign lo_y[32 * l +: 32] = lo_l[63:32]; assign lo_y32[32 * l +: 32] = lo_l[31:0];
    end endgenerate
    assign dbg_y32 = lo_y32;
    always @(posedge clk) begin
        l_d <= x_qd; l_role <= {8{tq[tr]}};
        if (push) tq[tw] <= {kv_slot, ij[0]};
        x_ra <= raddr;
        x_wd <= lo_y; x_wa <= sob + {nout[6:1], 2'b00} + {8'd0, nout[0], 1'b0}; x_wm <= 8'hFF;
    end
    // busy copies: set on an accepted command, cleared on fin (each copy from its own state)
    generate for (l = 0; l < NBZ; l = l + 1) begin : g_bz
        always @(posedge clk or negedge rl[l / 4]) begin
            if (!rl[l / 4]) bz[l] <= 1'b0;
            else if (go[l]) bz[l] <= 1'b1;
            else if (bz[l] && fin) bz[l] <= 1'b0;
        end
    end endgenerate
    // done, fault
    always @(posedge clk or negedge rl[0]) begin
        if (!rl[0]) begin done <= 1'b0; fault <= 1'b0; end
        else begin
            done <= 1'b0;
            if (start && (bz[1] || bad_cmd)) fault <= 1'b1;
            if (bz[1]) begin
                if ((pop && tn == 0 && !push) || (tn == 4'd8 && push && !pop)) fault <= 1'b1;
                if (|lf) fault <= 1'b1;
                if (lo_v[0] && lo_v != 8'hFF) fault <= 1'b1;
                if (fin) done <= 1'b1;
            end else if (pop || (|lo_v)) fault <= 1'b1;
        end
    end
    // issue edge (control), issuing copies, read valid
    always @(posedge clk or negedge rl[1]) begin
        if (!rl[1]) begin x_rv <= 1'b0; iss <= 2'd0; ie <= 10'd0; end
        else begin
            x_rv <= 1'b0;
            if (go[2]) begin iss <= 2'b11; ie <= 10'd0; end
            if (bz[2] && iss[0]) begin
                x_rv <= sc_slot || kv_slot;
                ie <= ie + 10'd1;
                if (ie == NE - 1) iss <= 2'b00;
            end
        end
    end
    // issue edge (address copy)
    always @(posedge clk or negedge rl[1]) begin
        if (!rl[1]) iec <= 10'd0;
        else if (go[3]) iec <= 10'd0;
        else if (bz[3] && iss[1]) iec <= iec + 10'd1;
    end
    // age
    always @(posedge clk or negedge rl[2]) begin
        if (!rl[2]) age <= 16'd0;
        else if (go[4]) age <= 16'd0;
        else if (bz[4]) age <= age + 16'd1;
    end
    // tag queue pointers
    always @(posedge clk or negedge rl[2]) begin
        if (!rl[2]) begin tw <= 3'd0; tr <= 3'd0; tn <= 4'd0; end
        else begin
            if (go[5]) begin tw <= 3'd0; tr <= 3'd0; tn <= 4'd0; end
            if (bz[5]) begin
                if (push) tw <= tw + 3'd1;
                if (pop) tr <= tr + 3'd1;
                tn <= tn + {3'd0, push} - {3'd0, pop};
            end
        end
    end
    // lane response valids
    always @(posedge clk or negedge rl[13]) if (!rl[13]) l_v <= 8'd0; else l_v <= {8{pop && bz[10]}};
    // write side
    always @(posedge clk or negedge rl[3]) begin
        if (!rl[3]) begin x_wv <= 1'b0; nout <= 7'd0; fin <= 1'b0; end
        else begin
            x_wv <= 1'b0;
            if (go[6]) nout <= 7'd0;
            if (bz[6]) begin
                if (lo_v[0]) begin
                    x_wv <= 1'b1;
                    nout <= nout + 7'd1;
                    if (nout == NG - 1) fin <= 1'b1;
                end
                if (fin) fin <= 1'b0;
            end
        end
    end
    // bases (reset as the original's control group)
    always @(posedge clk or negedge rl[12]) if (!rl[12]) sb0 <= 10'd0; else if (go[7]) sb0 <= b0;
    always @(posedge clk or negedge rl[12]) if (!rl[12]) sb1 <= 10'd0; else if (go[8]) sb1 <= b1;
    always @(posedge clk or negedge rl[13]) if (!rl[13]) sob <= 10'd0; else if (go[9]) sob <= ob;
endmodule

// ---- landing ring (verbatim rtl/dsrom_sys/s81_dv/land/ot_s81_land.sv)
`timescale 1ns/1ps
`default_nettype none
// ---------------------------------------------------------------------------------------------------------------------
// S81-LAND (2026-10-17, coordinator decision HANDOFF 0dm): the LANDING of a forwarded-clock die lane into a block.
// Contract: /home/ubuntu/claude-takeover-20261007/lanes/LANDING-CONTRACT.md (summary in results/arch/s81_dv_1016/landing/audit.json).
//
// The lane arrives on its own forwarded clock ck_f (the last relay station's ck_o, ~+115 ps per hop behind the source
// root); the block runs on its regional root ck.  Same frequency, unknown-but-FIXED phase dL = L(ck_f) - L(ck), which
// may exceed a period on a long lane and moves with corner / temperature.  The landing:
//   1. CAPTURE on ck_f: every ck_f edge writes the lane word into ring slot wc mod D (the slots ARE the capture flops:
//      flop-first, one hop like a relay stage; no pin register in front).  Bubbles are written too.
//   2. HANDOFF on ck: every ck edge after warm-up reads slot (rc - K) mod D into the registered output o (flop-last).
// No ready, no occupancy, no credit, no training: both pointers free-run from their epochs.
//
// Epochs (static calendar, compile-time):
//   * write epoch: wc counts ck_f edges from the FIRST one.  The lane's forwarded clock is started by the source: the
//     hop-0 forward cell is a clock gate opened at source edge G by the source's released reset (die netlist), so ck_f
//     edge 0 at the landing is source edge G whatever dL is.  wc is cleared asynchronously by rs while ck_f is
//     stopped (calendar: the block's reset releases at or before G), so no edge can race the release.
//   * read epoch:  rc counts ck edges from the release of rs (the block's regional synchronous reset, released on ck at
//     the region's calendar edge R0).
//   => o after ck edge m = the word written at ck_f edge m - R0 - K + G (K = strap k).  With E = K + R0 - G the compile-time latency
//      from the last relay station to o is E + 1 edges, INDEPENDENT of dL, provided
//          (E - D) * T + t_hold  <  dL  <  E * T - t_cq - t_setup                                     (window)
//      i.e. a D x T wide window (D = 4: ~3.0 ns at 833 ps).  The die STA checks it as the bank -> o path with
//      set_multicycle_path -setup E -hold (D - 1) at TT and FF with ONE E per lane.
// Fault (assertion only, never changes the calendar): every slot stores its write epoch wc; after warm-up the read slot's
// epoch must equal rc - K.  A slipped calendar (gate opened on the wrong edge, window violated, clock glitch) sets fault.
// Area: D x W slot flops + W output flops + 2 x (AW+1) pointer + D x (AW+1) epoch flops.
// ---------------------------------------------------------------------------------------------------------------------
module ot_s81_land #(
    parameter integer W  = 276,
    parameter integer D  = 4,       // ring depth (power of two, >= 2): window width in periods
    parameter integer AW = (D <= 2) ? 1 : $clog2(D),
    parameter integer KW = AW + 1   // LANDFIX-SQ (10-18): strap width.  KW = AW + 1 (default) = the original tiles
                                    // (1 <= K <= 2D-1).  A long lane (E > 2D-1, e.g. the 24-mm S81 host plane, E 28)
                                    // takes KW > AW + 1: the slot / epoch arithmetic stays mod 2D (2^KW is a multiple
                                    // of 2D), only the warm-up count uses the full K, so K = E + G - R0 needs no
                                    // reset-calendar offset between the source gate G and the receiver release R0.
) (
    input  wire [KW-1:0] k,         // read offset K: identity STRAP (die tie, compile-time per lane from the die STA dL
                                    // at TT and FF; 1 <= K <= 2^KW-1); case-analysed in the tile and die STA
    input  wire         ck_f,       // lane forwarded clock (last station ck_o)
    input  wire [W-1:0] i,          // lane data (last station o)
    input  wire         ck,         // block root clock
    input  wire         rs,         // block regional reset, active low (asynchronous assert, release synchronous on ck)
    output reg  [W-1:0] o,
    output reg          fault
);
    reg [W-1:0]  bank [0:D-1];
    reg [AW:0]   epo  [0:D-1];
    reg [AW:0]   wc;
    reg [KW-1:0] rc;                // read counter: low AW+1 bits = the read epoch; full width = the warm-up count
    reg          warm;
    // ------------------------------------------------------------------ write side (ck_f)
    always @(posedge ck_f or negedge rs)
        if (!rs) wc <= {(AW + 1){1'b0}};
        else     wc <= wc + 1'b1;
    genvar s;
    generate for (s = 0; s < D; s = s + 1) begin : g_slot
        always @(posedge ck_f)
            if (wc[AW-1:0] == s) begin bank[s] <= i; epo[s] <= wc; end   // no rs term: rs is a ck-domain net
    end endgenerate
    // ------------------------------------------------------------------ read side (ck)
`ifdef OT_S81_LAND_MUT_SEL
    wire [KW-1:0] expw = rc - k + 1'b1;        // bench mutant: read slot one late
`else
    wire [KW-1:0] expw = rc - k;
`endif
    wire [AW:0] exp_ = expw[AW:0];
    always @(posedge ck or negedge rs)
        if (!rs) begin rc <= {KW{1'b0}}; warm <= 1'b0; fault <= 1'b0; end
        else begin
            rc <= rc + 1'b1;
            if (rc == k - 1'b1) warm <= 1'b1;
            if (warm && epo[exp_[AW-1:0]] != exp_) fault <= 1'b1;
        end
`ifdef OT_S81_LAND_MUT_NAIVE
    // bench mutant: bounded-skew retime register only (no ring): o samples the lane directly on ck
    always @(posedge ck) o <= warm ? i : {W{1'b0}};
`else
    always @(posedge ck) o <= warm ? bank[exp_[AW-1:0]] : {W{1'b0}};
`endif
`ifndef SYNTHESIS
    initial if (D < 2 || (D & (D - 1)) != 0) $fatal(1, "ot_s81_land: D must be a power of two >= 2");
    initial if (KW < AW + 1) $fatal(1, "ot_s81_land: KW must be >= AW + 1");
    always @(posedge ck) if (warm && (k == 0)) $fatal(1, "ot_s81_land: strap k must be >= 1");
`endif
endmodule
`default_nettype wire
